files.bookings-api/bookings_api.py:
"""Booking flow: hold a bike, then charge the customer through payments-gateway."""

import requests

PAYMENTS_URL = "http://payments-gateway.internal:8080"
HOLD_MINUTES = 10
# payments-gateway takes up to 4 s per attempt and retries twice (3 attempts); stay within the 12s-25s need.
PAYMENT_TIMEOUT = 15


def hold(bike_id: str) -> dict:
    return {"bike_id": bike_id, "hold_minutes": HOLD_MINUTES}


def charge(booking):
    return requests.post(PAYMENTS_URL + "/charge", json=booking.to_payment(), timeout=PAYMENT_TIMEOUT)

