files.bookings-api/bookings_api.py:
"""Booking flow: hold a bike, then charge the customer through payments-gateway."""

import requests

from platform_config import http_timeout

PAYMENTS_URL = "http://payments-gateway.internal:8080"
HOLD_MINUTES = 10


def hold(bike_id: str) -> dict:
    return {"bike_id": bike_id, "hold_minutes": HOLD_MINUTES}


def charge(booking):
    return requests.post(
        PAYMENTS_URL + "/charge",
        json=booking.to_payment(),
        timeout=http_timeout("bookings-api"),
    )

files.admin-console/network.tf.json:
{
  "variable": {
    "vpc_id": {
      "description": "VPC the console runs in",
      "default": "vpc-0a1b2c3d"
    },
    "staff_vpn_cidr": {
      "description": "Address range of the staff VPN",
      "default": "10.20.0.0/16"
    }
  },
  "resource": {
    "aws_security_group_rule": {
      "admin_console_ingress": {
        "type": "ingress",
        "from_port": 443,
        "to_port": 443,
        "protocol": "tcp",
        "cidr_blocks": [
          "${var.staff_vpn_cidr}"
        ],
        "security_group_id": "${aws_security_group.admin_console.id}"
      }
    },
    "aws_security_group": {
      "admin_console": {
        "name": "admin-console",
        "vpc_id": "${var.vpc_id}"
      }
    }
  }
}

